CREATE OR REPLACE PROCEDURE public.sp_create_material_product(IN p_id uuid, IN p_sku character varying, IN p_name character varying, IN p_description text, IN p_category character varying, IN p_image_url character varying, IN p_material_type character varying, IN p_safety_instructions text, IN p_age_min_months integer, IN p_age_max_months integer, IN p_usage_restrictions text, IN p_cleaning_instructions text, IN p_return_policy text, IN p_is_active boolean, IN p_created_at timestamp with time zone, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     INSERT INTO material_products (         id, sku, name, description, category, image_url, material_type,         safety_instructions, age_min_months, age_max_months, usage_restrictions,         cleaning_instructions, return_policy, is_active, created_at, updated_at     ) VALUES (         p_id, p_sku, p_name, p_description, p_category, p_image_url, p_material_type,         p_safety_instructions, p_age_min_months, p_age_max_months, p_usage_restrictions,         p_cleaning_instructions, p_return_policy, p_is_active, p_created_at, p_updated_at     ); END; $procedure$ ;
